from pathlib import Path
import json,html,shutil
root=Path(__file__).parent;base=root.parent
variants=json.loads((root/'schemes.json').read_text())
style='''*{box-sizing:border-box}html{background:#050505;color:#eef8fc;font-family:system-ui,-apple-system,"Segoe UI",sans-serif;scroll-behavior:smooth}body{margin:0;padding:max(24px,env(safe-area-inset-top)) max(20px,env(safe-area-inset-right)) max(32px,env(safe-area-inset-bottom)) max(20px,env(safe-area-inset-left))}main{max-width:1180px;margin:auto}h1{font-size:clamp(22px,3vw,30px);line-height:1.35;margin:0 0 10px;font-weight:600}header p{font-size:14px;line-height:1.65;color:#a0adb2;margin:0}.nav{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0 24px}.nav a{min-height:44px;padding:10px 18px;border:1px solid #303638;border-radius:999px;color:#e5f4f8;text-decoration:none;font-size:13px}a:focus-visible{outline:2px solid #8fdceb;outline-offset:3px}.originals{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-bottom:34px}.originals figure{display:flex;align-items:center;justify-content:center;gap:14px;margin:0;padding:12px;background:#090b0c;border:1px solid #20272a;border-radius:18px}.originals img{width:clamp(70px,12vw,108px);height:auto}.originals figcaption{font-size:13px;color:#b9c9cf}.family{margin-top:36px;scroll-margin-top:24px}.section-head{display:flex;align-items:baseline;gap:12px;margin-bottom:16px;flex-wrap:wrap}.section-head h2{font-size:20px;font-weight:550;margin:0}.section-head span{font-size:12px;color:#829299}.grid{display:grid;grid-template-columns:1fr;gap:20px}.card{min-width:0;background:#090a0a;border:1px solid #22292c;border-radius:24px;padding:22px 20px 18px}.title{display:flex;align-items:center;gap:12px}.code{font-size:12px;font-weight:600;letter-spacing:.03em;padding:5px 9px;border-radius:7px;background:#1c2427;color:#d9edf4}h3{font-size:17px;font-weight:550;line-height:1.4;margin:0}.mark{display:block;width:100%;max-width:360px;height:auto;aspect-ratio:1;margin:14px auto 16px;border-radius:22px}.desc{font-size:13px;line-height:1.65;color:#9aa9af;min-height:44px;margin:0}.sizes{display:flex;align-items:center;gap:16px;flex-wrap:wrap;border-top:1px solid #20282c;margin-top:18px;padding-top:16px;min-height:122px}.sample{text-align:center;color:#788b94;font-size:11px}.sample img{display:block;margin:0 auto 6px}.source{margin-left:auto;padding:12px 0;color:#9ecbd8;font-size:12px;text-decoration:none}footer{margin-top:32px;border-top:1px solid #222b2f;padding-top:18px;color:#71848d;font-size:12px;line-height:1.7}footer a{color:#afcbd6;text-decoration:none}@media(min-width:760px){.grid{grid-template-columns:repeat(3,minmax(0,1fr))}.card{padding:20px 18px 16px}}@media(max-width:370px){.originals figure{gap:6px;padding:8px}.originals figcaption{font-size:12px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
s=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#000000"><meta name="color-scheme" content="dark"><title>贾维斯 · A 与 D 衍生六版</title><style>{style}</style></head><body><main>
<header><h1>贾维斯 · 两组衍生方案</h1><p>保留你认可的原 D、原 A，各自细化出 A／B／C。<br>两组统一画幅、配色和显示尺寸，方便对照。</p><nav class="nav" aria-label="方案分组"><a href="#family-d">D 系三版</a><a href="#family-a">A 系三版</a></nav></header>
<div class="originals"><figure><img src="original-D.svg" width="108" height="108" alt="你认可的原D倒三角核心"><figcaption>原 D<br>倒三角核心</figcaption></figure><figure><img src="original-A.svg" width="108" height="108" alt="你认可的原A圆形核心"><figcaption>原 A<br>圆形核心</figcaption></figure></div>'''
for family,caption in [('D','圆框＋倒三角核心'),('A','圆框＋同心环核心')]:
 s+=f'<section class="family" id="family-{family.lower()}"><div class="section-head"><h2>从原 {family} 出发</h2><span>{caption}</span></div><div class="grid">'
 for variant in ['A','B','C']:
  key=family+'-'+variant;data=variants[key]
  s+=f'''<article class="card" id="scheme-{key.lower()}"><div class="title"><span class="code">{key}</span><h3>{html.escape(data['name'])}</h3></div><img class="mark" src="reactor-{key}.svg" width="512" height="512" alt="{key}，{html.escape(data['description'])}"><p class="desc">{html.escape(data['description'])}</p><div class="sizes"><div class="sample"><img src="reactor-{key}-48.png" width="48" height="48" alt="{key}的48像素预览">48px</div><div class="sample"><img src="reactor-{key}-96.png" width="96" height="96" alt="{key}的96像素预览">96px</div><a class="source" href="reactor-{key}.svg">原图 ↗</a></div></article>'''
 s+='</div></section>'
s+='''<footer><a href="reactor-originals.html?v=originals">查看上一轮 A／B／C／D 与实物参考 ↗</a><p>当前供选形，尚未替换 App 图标。可以直接用 D-A、D-B、D-C 或 A-A、A-B、A-C 指定某一版。</p></footer></main></body></html>'''
(root/'review.html').write_text(s)
for key in ['A','D']:shutil.copy2(base/f'reactor-{key}.svg',root/f'original-{key}.svg')
(root/'reactor-originals.html').write_text((base/'review.html').read_text())
(root/'README.md').write_text('''# 原D与原A衍生六版（供选形）\n\n用户已认可原D和原A，分别要求衍生三个版本，D系和A系均保留。默认不选定、不发布到App。\n\nD-A：去掉外围刻度；D-B：增加中间圆环并保留线圈；D-C：三段开环。\nA-A：减少外圈细节；A-B：双线线圈；A-C：开环与六处短刻度。\n\n三角/圆形核心的位置与基础构图保持，六版统一画幅、配色。create_variants.py生成SVG与schemes.json，tools/preview_reactor.dart读取该目录导出48/96/512px用于检查。\n\n网页：http://192.168.1.101:18765/?v=reactor-six-v1\n当前未改App、未编译APK、未改后台服务。\n''')
print('Six-variant review page created')
